actions.script:
const out = ec.service.sync().name('org.moqui.call.VoicemailServices.update#VoicemailSettings').parameters({notifyEmail: notifyEmail || '',
    attachAudio: String(attachAudio) === 'true', attachTranscript: String(attachTranscript) === 'true', rings: rings || null})
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, box: out.box || null, warning: out.warning || null})

const out = ec.service.sync().name('org.moqui.call.VoicemailServices.set#VoicemailPin').parameters({pin: pin || '',
    clear: String(clear) === 'true'}).requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, box: out.box || null})

const out = ec.service.sync().name('org.moqui.call.VoicemailServices.store#VoicemailGreeting')
    .parameter('file', ec.web.multiPartParameters.file || null).requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, box: out.box || null})

const out = ec.service.sync().name('org.moqui.call.VoicemailServices.get#VoicemailGreeting').requireNewTransaction(true).disableAuthz().call() || {}
const refused = ec.message.hasError() || !out.location
ec.message.clearErrors()
if (refused) ec.web.sendJsonResponse({})
else ec.web.sendResourceResponse(out.location, true)
